// ignore_for_file: unused_element, unnecessary_cast

import 'logical_network_interface_network_type.dart';

/// Each logical network interface is effectively a network and IP pair.
class LogicalNetworkInterface {
  /// Whether this interface is the default gateway for the instance. Only one interface can be the default gateway for the instance.
  final bool? defaultGateway;
  /// An identifier for the `Network`, generated by the backend.
  final String? id;
  /// IP address in the network
  final String? ipAddress;
  /// Name of the network
  final String? network;
  /// Type of network.
  final LogicalNetworkInterfaceNetworkType? networkType;

  /// Creates a new [LogicalNetworkInterface].
  /// [defaultGateway] Whether this interface is the default gateway for the instance. Only one interface can be the default gateway for the instance.
  /// [id] An identifier for the `Network`, generated by the backend.
  /// [ipAddress] IP address in the network
  /// [network] Name of the network
  /// [networkType] Type of network.
  LogicalNetworkInterface({
    this.defaultGateway,
    this.id,
    this.ipAddress,
    this.network,
    this.networkType,
  });

  Map<String, dynamic> toMap() {
    return <String, dynamic>{
      'defaultGateway': ?defaultGateway,
      'id': ?id,
      'ipAddress': ?ipAddress,
      'network': ?network,
      'networkType': ?networkType == null ? null : networkType!.value,
    };
  }

  factory LogicalNetworkInterface.fromMap(Map<String, dynamic> map) {
    return LogicalNetworkInterface(
      defaultGateway: map['defaultGateway'] == null ? null : map['defaultGateway'] as bool,
      id: map['id'] == null ? null : map['id'] as String,
      ipAddress: map['ipAddress'] == null ? null : map['ipAddress'] as String,
      network: map['network'] == null ? null : map['network'] as String,
      networkType: map['networkType'] == null ? null : LogicalNetworkInterfaceNetworkType.fromValue(map['networkType'] as String),
    );
  }
}

